* 1. Operating Point Analysis
op
let idd = -i(VDD)
let p_diss = idd * 1.8
print idd p_diss

* 2. AC Analysis: Measure closed-loop and open-loop response
ac dec 50 10 1G

* Closed-loop gain: Vout / Vin
let acl_db = vdb(Vout)
meas ac acl_dc find acl_db at=10
meas ac f_3dBCL when acl_db={acl_dc - 3.0} fall=1

* Open-loop response: A_OL = Vout / (Vp - Vm)
let diff_in = v(vp) - v(vm)
let aol_mag = mag(v(Vout)) / (mag(diff_in) + 1e-18)
let aol_db = 20 * log10(aol_mag)
let aol_phase = (180/PI) * (cph(v(Vout)) - cph(diff_in))

meas ac open_loop_gain find aol_db at=10
meas ac unity_gain_frequency when aol_db=0 fall=1
meas ac phase_at_ugf find aol_phase when aol_db=0 fall=1
let pm = 180 + phase_at_ugf
print pm

* 3. Transient Analysis: Measure Slew Rates from Step Response
tran 0.2n 300n
* Falling edge of Vout (in response to rising Vin)
meas tran sr_fall trig v(Vout) val=1.3 fall=1 targ v(Vout) val=0.5 fall=1
let slew_rate_falling = (1.3 - 0.5) / (sr_fall * 1e6)

* Rising edge of Vout (in response to falling Vin)
meas tran sr_rise trig v(Vout) val=0.5 rise=1 targ v(Vout) val=1.3 rise=1
let slew_rate_rising = (1.3 - 0.5) / (sr_rise * 1e6)

print slew_rate_falling slew_rate_rising

quit
.endc
.end

